def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def ploon_xor(a, b):
    return (a ^ b) % 7

def grolp_sum(a, b):
    return (a + b + 3) % 7

def hidden_rule_fn(state):
    # Determine the next index (which is the length of the current state)
    next_index = len(state)

    # Get the last two elements
    a = state[-2]
    b = state[-1]

    if is_prime(next_index):
        new_val = ploon_xor(a, b)
    else:
        new_val = grolp_sum(a, b)

    return state + [new_val]
